import { MakeLogicType, connect, events, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { sessionRecordingsLiveCountRetrieve } from 'products/replay/frontend/generated/api'

// Matches the server-side cache TTL, so a faster poll would only return cached counts.
const POLL_INTERVAL_MS = 30000

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface liveRecordingsCountLogicValues {
    currentTeamId: number | null // teamLogic
    activeRecordings: number | null
    activeRecordingsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface liveRecordingsCountLogicActions {
    loadActiveRecordings: () => void
    loadActiveRecordingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadActiveRecordingsSuccess: (
        activeRecordings: number | null,
        payload?: any
    ) => {
        activeRecordings: number | null
        payload?: any
    }
}

export type liveRecordingsCountLogicType = MakeLogicType<
    liveRecordingsCountLogicValues,
    liveRecordingsCountLogicActions
>

export const liveRecordingsCountLogic = kea<liveRecordingsCountLogicType>([
    path(['scenes', 'session-recordings', 'components', 'liveRecordingsCountLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        activeRecordings: [
            null as number | null,
            {
                loadActiveRecordings: async () => {
                    if (values.currentTeamId === null) {
                        return values.activeRecordings
                    }
                    // A failed poll keeps the last count instead of toasting every interval.
                    try {
                        const response = await sessionRecordingsLiveCountRetrieve(String(values.currentTeamId))
                        return response.active_recordings
                    } catch {
                        return values.activeRecordings
                    }
                },
            },
        ],
    })),
    events(({ actions, cache }) => ({
        afterMount: () => {
            cache.disposables.add(() => {
                actions.loadActiveRecordings()
                const intervalId = setInterval(() => actions.loadActiveRecordings(), POLL_INTERVAL_MS)
                return () => clearInterval(intervalId)
            }, 'pollInterval')
        },
    })),
])
